(function () {
  var form = document.getElementById('add-form');
  var input = document.getElementById('item-input');
  var list = document.getElementById('list');
  var empty = document.getElementById('empty');
  var statusEl = document.getElementById('status');
  var items = new Map();

  function render() {
    var sorted = Array.from(items.values()).sort(function (a, b) { return a.id - b.id; });
    list.textContent = '';
    sorted.forEach(function (it) { list.appendChild(view(it)); });
    empty.hidden = sorted.length > 0;
  }

  function view(it) {
    var li = document.createElement('li');
    if (it.bought) li.className = 'done';
    var label = document.createElement('label');
    var cb = document.createElement('input');
    cb.type = 'checkbox';
    cb.checked = !!it.bought;
    cb.setAttribute('aria-label', 'Bought: ' + it.text);
    cb.addEventListener('change', function () { toggle(it.id, cb.checked, cb); });
    var span = document.createElement('span');
    span.className = 'text';
    span.textContent = it.text;
    label.appendChild(cb);
    label.appendChild(span);
    var rm = document.createElement('button');
    rm.type = 'button'; rm.className = 'ghost'; rm.textContent = 'Remove';
    rm.setAttribute('aria-label', 'Remove ' + it.text);
    rm.addEventListener('click', function () { remove(it.id); });
    li.appendChild(label);
    li.appendChild(rm);
    return li;
  }

  function apply(data) {
    if (Array.isArray(data.items)) {
      items = new Map(data.items.map(function (it) { return [it.id, it]; }));
      render();
    }
  }

  function load() {
    return fetch('/api/items', { cache: 'no-store' })
      .then(function (r) { return r.json(); })
      .then(function (d) { items = new Map(d.items.map(function (it) { return [it.id, it]; })); render(); });
  }

  form.addEventListener('submit', function (e) {
    e.preventDefault();
    var text = input.value.trim();
    if (!text) return;
    var btn = document.getElementById('add-button');
    btn.disabled = true;
    fetch('/api/items', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ text: text }) })
      .then(function (r) { return r.json().then(function (d) { if (!r.ok) throw new Error(d.error || 'failed'); return d; }); })
      .then(function (d) { input.value = ''; items.set(d.item.id, d.item); render(); })
      .catch(function (err) { alert('Could not add item: ' + err.message); })
      .then(function () { btn.disabled = false; input.focus(); });
  });

  function toggle(id, bought, cb) {
    fetch('/api/items/' + id, { method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ bought: bought }) })
      .then(function (r) { return r.json(); })
      .then(function (d) { if (d.item) { items.set(d.item.id, d.item); } render(); })
      .catch(function () { if (cb) cb.checked = !bought; });
  }
  function remove(id) {
    fetch('/api/items/' + id, { method: 'DELETE' })
      .then(function () { items.delete(id); render(); })
      .catch(function () {});
  }

  function setStatus(on) {
    statusEl.textContent = on ? 'live – changes appear instantly' : 'reconnecting…';
    statusEl.className = 'status ' + (on ? 'live' : 'off');
  }

  // Live updates: Server-Sent Events, with polling fallback so two people always converge within 5s.
  var es = null, pollTimer = null, lastSync = Date.now();
  function startPolling() {
    if (pollTimer) return;
    pollTimer = setInterval(function () { load().catch(function () {}); }, 2000);
  }
  function connect() {
    if (!window.EventSource) { setStatus(false); startPolling(); return; }
    es = new EventSource('/api/events');
    es.onopen = function () { setStatus(true); lastSync = Date.now(); };
    es.onmessage = function (ev) {
      lastSync = Date.now();
      try { apply(JSON.parse(ev.data)); } catch (e) {}
    };
    es.onerror = function () {
      setStatus(false);
      if (es.readyState === 2) { try { es.close(); } catch (e) {} setTimeout(connect, 1000); }
    };
  }
  // safety net: if no SSE traffic for a while, refresh from the API
  setInterval(function () { if (Date.now() - lastSync > 3000) { load().catch(function () {}); } }, 2500);

  load().catch(function () {}).then(connect);
})();
